1	// fix_necessity.go は、修正の必要度 (findings[].fix_necessity と fix_necessity_reason)・
2	// 必要度の下限 (runs[].min_fix_necessity)・判定「下限未満」(verdict: below_minimum)・
3	// 下限未満の指摘の参照 (findings[].below_minimum_ref) の検査と、生成サマリへの描画を持つ。
4	// 判定の条件の SSOT は skills/review-triage/references/judgment-flow.md の D9〜D12・E3、
5	// キーの意味の SSOT は同じディレクトリの record-schema.md。
6	package main
7	
8	import (
9		"fmt"
10		"strings"
11	)
12	
13	// recordFixNecessityReason は findings[].fix_necessity_reason を表し、E3 の 2 つの条件の
14	// 結果を持つ。goal_without_action は条件 1 (困る人は、何もしなくても目的を達成できるか)、
15	// workaround は条件 2 (困る人が気づいて取れる回避策があるか) の結果で、条件 1 が not-holds の
16	// ときだけ書く。必要度 (fix_necessity) はこの結果から決まる (fixNecessityFromReason)。
17	// 判定理由の文に書く形にしないのは、書き忘れを検査で見つけられないため (prior_defect と同じ)。
18	type recordFixNecessityReason struct {
19		GoalWithoutAction string `yaml:"goal_without_action"`
20		Workaround        string `yaml:"workaround"`
21		WorkaroundReason  string `yaml:"workaround_reason"`
22	}
23	
24	// recordBelowMinimumRef は findings[].below_minimum_ref を表す。D9 の (1) (前の回までの
25	// 下限未満の指摘と問題が同じ) が成り立った指摘に書く。run と finding は参照先 (1 始まりの
26	// 回番号と、その回の指摘の id)、line_check は D9 の (2) (対象の行が変わっていない) の結果。
27	type recordBelowMinimumRef struct {
28		Run        int    `yaml:"run"`
29		Finding    int    `yaml:"finding"`
30		LineCheck  string `yaml:"line_check"`
31		LineReason string `yaml:"line_reason"`
32	}
33	
34	// fixNecessityRank は必要度の高さを返す (must が最も高い)。列挙に無い値は 0。
35	func fixNecessityRank(v string) int {
36		switch v {
37		case "must":
38			return 3
39		case "should":
40			return 2
41		case "could":
42			return 1
43		}
44		return 0
45	}
46	
47	// fixNecessityJa は必要度を生成サマリに出す表記にする。
48	func fixNecessityJa(v string) string {
49		switch v {
50		case "must":
51			return "Must"
52		case "should":
53			return "Should"
54		case "could":
55			return "Could"
56		}
57		return recordCell(v)
58	}
59	
60	// fixNecessityBelow は、必要度が下限に満たないかを返す。下限が無ければ満たないことは無い。
61	// どちらかが列挙に無い値のときは、比べられないので偽を返す (列挙の誤りは別に報告する)。
62	func fixNecessityBelow(necessity, minimum string) bool {
63		n, m := fixNecessityRank(necessity), fixNecessityRank(minimum)
64		return n > 0 && m > 0 && n < m
65	}
66	
67	// fixNecessityFromReason は、2 つの条件の結果から決まる必要度を返す。どちらかの条件が
68	// undecided なら空 (必要度を付けない)。ok が偽なら、結果の形が誤っていて決まらない。
69	func fixNecessityFromReason(r *recordFixNecessityReason) (necessity string, ok bool) {
70		switch r.GoalWithoutAction {
71		case "holds":
72			return "could", r.Workaround == ""
73		case "undecided":
74			return "", r.Workaround == ""
75		case "not-holds":
76			switch r.Workaround {
77			case "holds":
78				return "should", true
79			case "not-holds":
80				return "must", true
81			case "undecided":
82				return "", true
83			}
84		}
85		return "", false
86	}
87	
88	// judgmentOmitted は、D9 で当たって判定を省略した指摘 (A3・B2) かを返す。
89	func judgmentOmitted(fd recordFinding) bool {
90		return fd.BelowMinimumRef != nil && fd.BelowMinimumRef.LineCheck == "holds"
91	}
92	
93	// recordFixNecessityFirstRun は、記録の中で最初に fix_necessity_reason を書いた回の添字を
94	// 返す。無ければ -1。この回と、それより後の回では fix_necessity_reason を必須にする。
95	// 決め方と理由は recordPriorDefectFirstRun と同じ (過去の記録を書き換えさせずに通すため)。
96	func recordFixNecessityFirstRun(runs []recordRun) int {
97		for ri, run := range runs {
98			for _, fd := range run.Findings {
99				if fd.FixNecessityReason != nil {
100					return ri
101				}
102			}
103		}
104		return -1
105	}
106	
107	// recordFixNecessityProblems は、判定を省略していない指摘 1 件の必要度を検査する。
108	// 書く条件は E3 を行ったかで決まる。判定フローでは、D4 で根拠を確認した指摘
109	// (premise_check.result が verified) だけが E3 に進む。required が偽の回
110	// (recordFixNecessityFirstRun の回より前の回) では、無くても報告しない。
111	// minimum はその回の必要度の下限 (無ければ空)。
112	func recordFixNecessityProblems(required bool, minimum string, fd recordFinding) []string {
113		var problems []string
114		add := func(format string, args ...any) {
115			problems = append(problems, fmt.Sprintf(format, args...))
116		}
117		if fd.FixNecessity != "" && fixNecessityRank(fd.FixNecessity) == 0 {
118			add("fix_necessity は must / should / could のいずれか (決められなければ書かない): %q", fd.FixNecessity)
119		}
120		// 下限未満にできるのは、必要度を決めた指摘だけ。必要度の無い下限未満は、下の対応の
121		// 検査では見つからない (理由の無い指摘と、決められなかった指摘の両方がある) ので、ここで見る。
122		if fd.Verdict == "below_minimum" && fd.FixNecessity == "" {
123			add("verdict が below_minimum なのに fix_necessity がありません (下限未満にできるのは、必要度を決めた指摘だけ)")
124		}
125		verified := fd.PremiseCheck.Result == "verified"
126		r := fd.FixNecessityReason
127		if r == nil {
128			switch {
129			case fd.FixNecessity != "":
130				add("fix_necessity があるのに fix_necessity_reason がありません (必要度は、E3 の 2 つの条件の結果から決める)")
131			case verified && required:
132				add("fix_necessity_reason がありません (D4 で根拠を確認した指摘は E3 で必要度を判定するので、条件の結果を書く。この記録では、この回かそれより前の回で fix_necessity_reason を書いている)")
133			}
134			return problems
135		}
136		if !verified {
137			// E3 に進んでいない指摘の必要度は、どの値でも判定の経路と矛盾するので、中身は検査しない。
138			add("fix_necessity_reason は E3 を行った指摘 (premise_check.result が verified) にだけ書く (result %q)", fd.PremiseCheck.Result)
139			return problems
140		}
141		shapeValid := true
142		switch r.GoalWithoutAction {
143		case "holds", "not-holds", "undecided":
144		default:
145			shapeValid = false
146			add("fix_necessity_reason.goal_without_action は holds / not-holds / undecided のいずれか: %q", r.GoalWithoutAction)
147		}
148		switch {
149		case r.GoalWithoutAction == "not-holds":
150			switch r.Workaround {
151			case "holds", "not-holds", "undecided":
152			case "":
153				shapeValid = false
154				add("fix_necessity_reason.workaround がありません (goal_without_action が not-holds なら条件 2 を判定する)")
155			default:
156				shapeValid = false
157				add("fix_necessity_reason.workaround は holds / not-holds / undecided のいずれか: %q", r.Workaround)
158			}
159			if r.Workaround != "" && r.WorkaroundReason == "" {
160				add("fix_necessity_reason.workaround_reason がありません (回避策の手段か、無い理由か、決められなかった理由)")
161			}
162		case shapeValid:
163			// 条件 1 が成り立つか決められなければ、条件 2 は判定しない。
164			if r.Workaround != "" || r.WorkaroundReason != "" {
165				shapeValid = false
166				add("fix_necessity_reason.workaround と workaround_reason は、goal_without_action が not-holds のときだけ書く (goal_without_action %q)", r.GoalWithoutAction)
167			}
168		}
169		if !shapeValid {
170			return problems
171		}
172		want, _ := fixNecessityFromReason(r)
173		if fd.FixNecessity != want {
174			if want == "" {
175				add("fix_necessity_reason では必要度が決まらない (undecided がある) のに、fix_necessity %q があります", fd.FixNecessity)
176			} else {
177				add("fix_necessity は、fix_necessity_reason から決まる %s と違います: %q", want, fd.FixNecessity)
178			}
179			return problems
180		}
181		switch {
182		case want == "" && fd.Verdict == "adopted":
183			add("必要度を決められなかった (fix_necessity_reason に undecided がある) のに、verdict が adopted です (決められなければ H8 の保留)")
184		case fd.Verdict == "adopted" && fixNecessityBelow(want, minimum):
185			add("必要度 %s が回の下限 %s に満たないのに、verdict が adopted です (下限に満たなければ B1 の下限未満)", want, minimum)
186		case fd.Verdict == "below_minimum" && want != "" && !fixNecessityBelow(want, minimum):
187			if minimum == "" {
188				add("回に下限 (min_fix_necessity) が無いのに、verdict が below_minimum です")
189			} else {
190				add("必要度 %s が回の下限 %s 以上なのに、verdict が below_minimum です", want, minimum)
191			}
192		}
193		return problems
194	}
195	
196	// belowMinimumRefTarget は below_minimum_ref の参照先の指摘を返す。参照先にできるのは、
197	// この回 (添字 ri) より前の回の、必要度を判定して下限未満にした指摘 (B1) だけ。
198	// 判定を省略した指摘 (B2) は必要度を持たないので、参照先にしない。
199	func belowMinimumRefTarget(doc *recordDoc, ri int, ref *recordBelowMinimumRef) (*recordFinding, string) {
200		if ref.Run < 1 || ref.Run > ri {
201			return nil, fmt.Sprintf("below_minimum_ref の run %d は、この回より前の回ではありません (この回は %d 回目)", ref.Run, ri+1)
202		}
203		findings := doc.Runs[ref.Run-1].Findings
204		for i := range findings {
205			if findings[i].ID != ref.Finding {
206				continue
207			}
208			t := &findings[i]
209			if t.Verdict != "below_minimum" || fixNecessityRank(t.FixNecessity) == 0 {
210				return nil, fmt.Sprintf("below_minimum_ref の参照先 (%d 回目の id %d) は、必要度を判定して下限未満にした指摘ではありません (verdict %q / fix_necessity %q)",
211					ref.Run, ref.Finding, t.Verdict, t.FixNecessity)
212			}
213			return t, ""
214		}
215		return nil, fmt.Sprintf("below_minimum_ref の finding %d は %d 回目の findings にありません", ref.Finding, ref.Run)
216	}
217	
218	// recordBelowMinimumRefProblems は指摘 1 件の below_minimum_ref と、それに関わるキーを検査する。
219	func recordBelowMinimumRefProblems(doc *recordDoc, ri int, fd recordFinding) []string {
220		var problems []string
221		add := func(format string, args ...any) {
222			problems = append(problems, fmt.Sprintf(format, args...))
223		}
224		ref := fd.BelowMinimumRef
225		if ref == nil {
226			if fd.Origin == "prior_below_minimum" {
227				add("origin が prior_below_minimum なのに below_minimum_ref がありません (足した指摘は、前の回のどの指摘かを書く)")
228			}
229			return problems
230		}
231		target, msg := belowMinimumRefTarget(doc, ri, ref)
232		if msg != "" {
233			add("%s", msg)
234		}
235		switch ref.LineCheck {
236		case "holds", "not-holds", "unverifiable":
237		default:
238			add("below_minimum_ref.line_check は holds / not-holds / unverifiable のいずれか: %q", ref.LineCheck)
239		}
240		if ref.LineReason == "" {
241			add("below_minimum_ref.line_reason がありません (対象の行が変わっていないかの結果の理由)")
242		}
243		if !judgmentOmitted(fd) {
244			return problems
245		}
246		// 判定を省略した指摘 (A3・B2)。分類・被害者・帰結・根拠の検証・ゲート・必要度は書かない。
247		// 書いてあると、参照先の値と、この指摘の値のどちらを読むのかが決まらない。
248		for _, kv := range []struct {
249			key     string
250			written bool
251		}{
252			{"category", fd.Category != ""},
253			{"audience", fd.Audience != ""},
254			{"audience_initial", fd.AudienceInitial != ""},
255			{"consequence", fd.Consequence != recordConsequence{}},
256			{"premise_check", fd.PremiseCheck != recordPremise{}},
257			{"gates_fired", len(fd.GatesFired) > 0},
258			{"prior_defect", fd.PriorDefect != nil},
259			{"fix_necessity", fd.FixNecessity != ""},
260			{"fix_necessity_reason", fd.FixNecessityReason != nil},
261		} {
262			if kv.written {
263				add("判定を省略した指摘 (below_minimum_ref.line_check が holds) では %s を書かない (参照先の指摘のものを読む)", kv.key)
264			}
265		}
266		if target == nil {
267			return problems
268		}
269		// D12: 参照先の必要度が、この回の下限以上なら採択 (A3)、満たなければ下限未満 (B2)。
270		want := "adopted"
271		if fixNecessityBelow(target.FixNecessity, doc.Runs[ri].MinFixNecessity) {
272			want = "below_minimum"
273		}
274		if fd.Verdict != want {
275			minimum := doc.Runs[ri].MinFixNecessity
276			if minimum == "" {
277				minimum = "無し"
278			}
279			add("判定を省略した指摘の verdict は、参照先の必要度 %s と回の下限 %s から %s に決まりますが、%q です",
280				target.FixNecessity, minimum, want, fd.Verdict)
281		}
282		return problems
283	}
284	
285	// findingFixNecessity は指摘の必要度を返す。判定を省略した指摘は、参照先の必要度。
286	// 分からなければ空。
287	func findingFixNecessity(doc *recordDoc, ri int, fd recordFinding) string {
288		if !judgmentOmitted(fd) {
289			return fd.FixNecessity
290		}
291		if target, _ := belowMinimumRefTarget(doc, ri, fd.BelowMinimumRef); target != nil {
292			return target.FixNecessity
293		}
294		return ""
295	}
296	
297	// renderFixNecessityCounts は推移の表の必要度の 3 列 (Must・Should・Could) を返す。
298	// 判定に関わらず、その回で必要度が分かる指摘を数える。fix_necessity_reason を書き始める前の
299	// 回 (firstRun より前。1 度も書いていない記録ではすべての回) は「—」にする。0 と書くと、
300	// 必要度を判定して 0 件だったように読めるため。
301	func renderFixNecessityCounts(doc *recordDoc, ri, firstRun int) []string {
302		if firstRun < 0 || ri < firstRun {
303			return []string{"—", "—", "—"}
304		}
305		counts := map[string]int{}
306		for _, fd := range doc.Runs[ri].Findings {
307			counts[findingFixNecessity(doc, ri, fd)]++
308		}
309		return []string{
310			fmt.Sprint(counts["must"]), fmt.Sprint(counts["should"]), fmt.Sprint(counts["could"]),
311		}
312	}
313	
314	// belowMinimumEntry は、節「下限未満の指摘」の 1 行になる指摘 (必要度を判定して下限未満に
315	// した指摘)。resolved は、後の回の指摘が参照して、判定し直したか採択 (A3) にしたこと。
316	// reported は、同じ問題がまた報告されて判定を省略した指摘 (B2) の位置。
317	type belowMinimumEntry struct {
318		run      int
319		finding  recordFinding
320		resolved bool
321		reported []string
322	}
323	
324	// renderBelowMinimumSection は節「下限未満の指摘」を書く。記録に下限未満の指摘が 1 件も
325	// 無ければ何も書かない。並べるのは残っている指摘だけで、必要度ごとの表にする。
326	// 件数はここで数え、人が書いた集計をどこからも読まない (推移の表と同じ)。
327	func renderBelowMinimumSection(b *strings.Builder, doc *recordDoc) {
328		var entries []*belowMinimumEntry
329		index := map[[2]int]*belowMinimumEntry{}
330		hasBelowMinimum := false
331		for ri, run := range doc.Runs {
332			for _, fd := range run.Findings {
333				if fd.Verdict == "below_minimum" {
334					hasBelowMinimum = true
335				}
336				if ref := fd.BelowMinimumRef; ref != nil {
337					if e := index[[2]int{ref.Run, ref.Finding}]; e != nil {
338						if judgmentOmitted(fd) && fd.Verdict == "below_minimum" {
339							e.reported = append(e.reported, fmt.Sprintf("%d 回目 #%d", ri+1, fd.ID))
340						} else {
341							e.resolved = true
342						}
343					}
344				}
345				if fd.Verdict == "below_minimum" && fixNecessityRank(fd.FixNecessity) > 0 {
346					e := &belowMinimumEntry{run: ri + 1, finding: fd}
347					entries = append(entries, e)
348					index[[2]int{ri + 1, fd.ID}] = e
349				}
350			}
351		}
352		if !hasBelowMinimum {
353			return
354		}
355		b.WriteString("\n## 下限未満の指摘\n")
356		remaining := 0
357		for _, necessity := range []string{"must", "should", "could"} {
358			var rows []*belowMinimumEntry
359			for _, e := range entries {
360				if !e.resolved && e.finding.FixNecessity == necessity {
361					rows = append(rows, e)
362				}
363			}
364			if len(rows) == 0 {
365				continue
366			}
367			remaining += len(rows)
368			fmt.Fprintf(b, "\n### %s (%d 件)\n\n", fixNecessityJa(necessity), len(rows))
369			b.WriteString("| 判定した回 | 指摘 | 回避策 | また報告された回 |\n")
370			b.WriteString("| --- | --- | --- | --- |\n")
371			for _, e := range rows {
372				b.WriteString(recordRow(renderBelowMinimumCells(e)))
373			}
374		}
375		if remaining == 0 {
376			b.WriteString("\n残っている下限未満の指摘はありません (後の回で判定し直したか、採択にした)。\n")
377		}
378	}
379	
380	// renderBelowMinimumCells は節「下限未満の指摘」の 1 行のセルのスライスを返す。
381	func renderBelowMinimumCells(e *belowMinimumEntry) []string {
382		fd := e.finding
383		loc := fd.File
384		if fd.Line > 0 {
385			loc = fmt.Sprintf("%s:%d", fd.File, fd.Line)
386		}
387		// 回避策は、条件 2 を判定した指摘 (Should) だけが持つ。条件 1 が成り立つ指摘 (Could) は
388		// 何もしなくても目的を達成できるので、回避策を書かない。
389		workaround := "—"
390		if r := fd.FixNecessityReason; r != nil && r.WorkaroundReason != "" {
391			workaround = recordCell(r.WorkaroundReason)
392		}
393		reported := "—"
394		if len(e.reported) > 0 {
395			reported = strings.Join(e.reported, "、")
396		}
397		return []string{
398			fmt.Sprintf("%d 回目 #%d", e.run, fd.ID),
399			"`" + recordCell(loc) + "` " + recordCell(fd.Summary),
400			workaround,
401			reported,
402		}
403	}
404	
405	// renderFixNecessityNote は、判定セルに添える必要度と、下限未満の指摘の参照を返す。
406	// どちらも無い指摘では空。過去の記録の判定セルを変えないため。
407	func renderFixNecessityNote(fd recordFinding) string {
408		var note string
409		if fd.FixNecessityReason != nil {
410			necessity := "決められない"
411			if fd.FixNecessity != "" {
412				necessity = fixNecessityJa(fd.FixNecessity)
413			}
414			note += " (必要度: " + necessity + ")"
415		}
416		if ref := fd.BelowMinimumRef; ref != nil {
417			if judgmentOmitted(fd) {
418				note += fmt.Sprintf(" (%d 回目の #%d と同じ)", ref.Run, ref.Finding)
419			} else {
420				note += fmt.Sprintf(" (%d 回目の #%d と同じ問題を判定し直した)", ref.Run, ref.Finding)
421			}
422		}
423		return note
424	}
425

